<?php
require __DIR__.'/config/bootstrap.php';require_once __DIR__.'/includes/layout.php';$user=require_login();$id=(int)($_GET['id']??0);
if($user['role']==='admin'&&$id>0){$s=$pdo->prepare('SELECT p.*,u.nama,u.nip,u.jabatan,u.divisi FROM payroll p JOIN users u ON u.id=p.user_id WHERE p.id=?');$s->execute([$id]);}
elseif($user['role']==='karyawan'){$s=$pdo->prepare('SELECT p.*,u.nama,u.nip,u.jabatan,u.divisi FROM payroll p JOIN users u ON u.id=p.user_id WHERE p.user_id=? ORDER BY p.tahun DESC,p.bulan DESC');$s->execute([$user['id']]);}
else{$s=$pdo->prepare('SELECT p.*,u.nama,u.nip,u.jabatan,u.divisi FROM payroll p JOIN users u ON u.id=p.user_id ORDER BY p.tahun DESC,p.bulan DESC LIMIT 100');$s->execute();}
$rows=$s->fetchAll();page_header('Slip gaji'); ?>
<div class="d-flex justify-content-between align-items-end mb-4 no-print"><div><div class="eyebrow">Dokumen penggajian</div><h1 class="page-title mb-0">Slip gaji</h1></div><?php if($id&&$rows): ?><button class="btn btn-primary" onclick="window.print()"><i class="fa-solid fa-print me-2"></i>Cetak / PDF</button><?php endif;?></div>
<?php if(!$id||$user['role']==='karyawan'): ?><section class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Periode</th><?php if($user['role']==='admin'):?><th>Karyawan</th><?php endif;?><th>Take-home pay</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('F Y',mktime(0,0,0,(int)$r['bulan'],1,(int)$r['tahun'])))?></td><?php if($user['role']==='admin'):?><td><?=e($r['nama'])?> · <?=e($r['nip'])?></td><?php endif;?><td class="fw-bold"><?=rupiah($r['total_take_home_pay'])?></td><td><?=e(ucfirst($r['status_bayar']))?></td><td><a class="btn btn-outline-primary btn-sm" href="?id=<?=(int)$r['id']?>">Lihat slip</a></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else: foreach($rows as $r): ?><article class="panel mx-auto" style="max-width:760px"><div class="d-flex justify-content-between border-bottom pb-3 mb-3"><div><div class="eyebrow">PresensiKu · Slip Gaji</div><h2 class="h4 fw-bold mb-1">Rincian penghasilan</h2><div class="text-secondary"><?=e(date('F Y',mktime(0,0,0,(int)$r['bulan'],1,(int)$r['tahun'])))?></div></div><span class="badge text-bg-<?=$r['status_bayar']==='dibayar'?'success':'secondary'?> align-self-start"><?=e(strtoupper($r['status_bayar']))?></span></div><div class="row mb-4"><div class="col"><strong><?=e($r['nama'])?></strong><div class="small text-secondary"><?=e($r['nip'])?> · <?=e($r['jabatan'])?> · <?=e($r['divisi'])?></div></div></div><table class="table"><tbody><tr><td colspan="2" class="fw-bold">Pendapatan</td></tr><tr><td>Gaji pokok</td><td class="text-end"><?=rupiah($r['gaji_pokok'])?></td></tr><tr><td>Tunjangan makan</td><td class="text-end"><?=rupiah($r['tunjangan_makan'])?></td></tr><tr><td>Tunjangan transport</td><td class="text-end"><?=rupiah($r['tunjangan_transport'])?></td></tr><tr><td>Uang lembur (<?=number_format((float)$r['total_lembur_jam'],1)?> jam)</td><td class="text-end"><?=rupiah($r['uang_lembur'])?></td></tr><tr><td colspan="2" class="fw-bold pt-4">Potongan</td></tr><tr><td>Keterlambatan (<?=(int)$r['total_terlambat']?> jam)</td><td class="text-end">− <?=rupiah($r['potongan_terlambat'])?></td></tr><tr><td>Alpha</td><td class="text-end">− <?=rupiah($r['potongan_alpha'])?></td></tr><tr><td>BPJS</td><td class="text-end">− <?=rupiah($r['potongan_bpjs'])?></td></tr><tr class="border-top"><th>Total take-home pay</th><th class="text-end fs-5 text-success"><?=rupiah($r['total_take_home_pay'])?></th></tr></tbody></table><div class="small text-secondary mt-4">Jumlah hadir: <?=(int)$r['total_hadir']?> hari · Tanggal bayar: <?=e($r['tanggal_bayar']?:'Belum dibayar')?></div><div class="print-only mt-5 text-end">HRD PresensiKu</div></article><?php endforeach; endif;?>
<?php page_footer(); ?>
